import type { Cookie, Locator, Page } from '@playwright/test';
import BasePage from '../base-page';
import { cookiebot } from '../../test-data/consent';

export interface CookiebotConsent {
  necessary: boolean;
  preferences: boolean;
  statistics: boolean;
  marketing: boolean;
  method: string | null;
}

export default class CookieBanner extends BasePage {
  readonly dialog: Locator;
  readonly allowAllButton: Locator;
  readonly denyButton: Locator;

  constructor(page: Page) {
    super(page);
    // Cookiebot's own element id; identical on every Cookiebot site and not generated by Bricks.
    this.dialog = page.locator('#CybotCookiebotDialog');
    this.allowAllButton = this.dialog.getByRole('button', { name: cookiebot.bannerTexts.allowAll, exact: true });
    this.denyButton = this.dialog.getByRole('button', { name: cookiebot.bannerTexts.deny, exact: true });
  }

  async acceptAll(): Promise<void> {
    await this.clickElement(this.allowAllButton);
    await this.dialog.waitFor({ state: 'hidden' });
  }

  async denyAll(): Promise<void> {
    await this.clickElement(this.denyButton);
    await this.dialog.waitFor({ state: 'hidden' });
  }

  async waitForCookiebot(): Promise<void> {
    await this.page.waitForFunction(() => typeof window.Cookiebot?.consent === 'object');
  }

  async getConsent(): Promise<CookiebotConsent> {
    await this.waitForCookiebot();
    return this.page.evaluate(() => {
      const { necessary, preferences, statistics, marketing, method } = window.Cookiebot!.consent;
      return { necessary, preferences, statistics, marketing, method };
    });
  }

  async getConsentCookie(): Promise<Cookie | undefined> {
    const cookies = await this.page.context().cookies();
    return cookies.find((cookie) => cookie.name === cookiebot.consentCookieName);
  }
}
